/**
 * The key each gamepad button presses until the URL remaps it, by its index in the browser's standard mapping: A (0),
 * Start (9) and the D-pad's up, down, left and right (12 to 15). The D-pad presses the "Snapper" keys.
 */
export const BbcGamepadKeys = {
    0: BBC.RETURN,
    9: BBC.SPACE,
    12: BBC.COLON_STAR,
    13: BBC.SLASH,
    14: BBC.Z,
    15: BBC.X,
};

const IsLetter = /^[A-Za-z]$/;

/** BBC keys that print the same thing either way, so holding one must not disturb shift. */
const ShiftMakesNoDifference = new Set([BBC.SPACE]);

/** The characters a natural layout tries to bind, of which each machine takes those it can print. */
export const PrintableCharacters = (() => {
    const chars = ["\u00a3"];
    for (let code = 32; code < 127; ++code) chars.push(String.fromCharCode(code));
    return chars;
})();

/**
 * How a natural layout binds a host key, a character or a position, to the key that makes `char`.
 * The machine holds shift for a different set of characters than a PC does, so a key says which
 * shift state it needs, as a third element, when that differs from the one being held.
 *
 * @param {Function} map binds (hostKey, colRow, shiftDown)
 * @param {Function} keyForCharacter as `bbcKeyForCharacter`
 * @param {Set} keysShiftLeavesAlone keys that print the same thing either way
 * @returns {Function} binds (hostKey, char)
 */
export function characterBinder(map, keyForCharacter, keysShiftLeavesAlone) {
    return (hostKey, char) => {
        const needs = keyForCharacter(char);
        if (!needs) return;
        for (const shiftDown of [false, true]) {
            // Overriding when the two already agree would take shift away from everything
            // else held at the same time, and letters want the shift key as it is anyway.
            const disagrees = needs.shift !== shiftDown && !IsLetter.test(char) && !keysShiftLeavesAlone.has(needs.key);
            map(hostKey, disagrees ? [...needs.key, needs.shift] : needs.key, shiftDown);
        }
    };
}

/**
 * How a BBC keyboard types a character: which key, and whether shift is held while it is
 * pressed. `!` is shift and `1`; `^` is its own unshifted key. Lower case is the same key as
 * upper with the caps lock the other way, which `upperCase` says.
 *
 * The one table for this; the natural keyboard layout and pasting both read it.
 *
 * @param {string} char one character
 * @returns {{key: [number, number], shift: boolean, upperCase: boolean}|null} null if the BBC has no such character
 */
export function bbcKeyForCharacter(char) {
    const code = char.charCodeAt(0);
    if (code >= 65 && code <= 90) return { key: BBC[char], shift: false, upperCase: true };
    if (code >= 97 && code <= 122) return { key: BBC[String.fromCharCode(code - 32)], shift: false, upperCase: false };
    if (code >= 48 && code <= 57) return { key: BBC["K" + char], shift: false, upperCase: true };
    const shifted = ShiftedCharacters[char];
    if (shifted) return { key: shifted, shift: true, upperCase: true };
    const unshifted = UnshiftedCharacters[char];
    if (unshifted) return { key: unshifted, shift: false, upperCase: true };
    return null;
}

/** Characters the BBC prints with shift held. `!` to `)` are shift and the digit above them. */
const ShiftedCharacters = {
    "!": BBC.K1,
    '"': BBC.K2,
    "#": BBC.K3,
    $: BBC.K4,
    "%": BBC.K5,
    "&": BBC.K6,
    "'": BBC.K7,
    "(": BBC.K8,
    ")": BBC.K9,
    "=": BBC.MINUS,
    "~": BBC.HAT_TILDE,
    "|": BBC.PIPE_BACKSLASH,
    "{": BBC.LEFT_SQUARE_BRACKET,
    "+": BBC.SEMICOLON_PLUS,
    "*": BBC.COLON_STAR,
    "}": BBC.RIGHT_SQUARE_BRACKET,
    "<": BBC.COMMA,
    ">": BBC.PERIOD,
    "?": BBC.SLASH,
    // Character 96, where ASCII has a backtick: the MOS font at &C000 draws a pound sign.
    "\u00a3": BBC.UNDERSCORE_POUND,
};

/** Characters the BBC prints without shift. */
const UnshiftedCharacters = {
    "\n": BBC.RETURN,
    "\t": BBC.TAB,
    " ": BBC.SPACE,
    "-": BBC.MINUS,
    "^": BBC.HAT_TILDE,
    "\\": BBC.PIPE_BACKSLASH,
    "@": BBC.AT,
    "[": BBC.LEFT_SQUARE_BRACKET,
    _: BBC.UNDERSCORE_POUND,
    ";": BBC.SEMICOLON_PLUS,
    ":": BBC.COLON_STAR,
    "]": BBC.RIGHT_SQUARE_BRACKET,
    ",": BBC.COMMA,
    ".": BBC.PERIOD,
    "/": BBC.SLASH,
};

/**
 * The keys to press, in order, to type `str`, toggling `shiftKey` and `lockKey` as each character needs them and
 * leaving both as they were found.
 * @param {string} str
 * @param {function(string): ?{key: number[], shift: boolean, upperCase?: boolean}} keyForCharacter where
 *     `upperCase` is left out for a character the lock does not change
 * @param {number[]} shiftKey
 * @param {number[]} lockKey
 */
export function stringToKeys(str, keyForCharacter, shiftKey, lockKey) {
    const array = [];
    let shiftState = false;
    let capsLockState = true;
    for (const char of str) {
        const needs = keyForCharacter(char);
        if (!needs) continue;

        if (needs.shift !== shiftState) {
            array.push(shiftKey);
            shiftState = needs.shift;
        }
        if (needs.upperCase !== undefined && needs.upperCase !== capsLockState) {
            array.push(lockKey);
            capsLockState = needs.upperCase;
        }
        array.push(needs.key);
    }

    if (shiftState) array.push(shiftKey);
    if (!capsLockState) array.push(lockKey);
    return array;
}

export function stringToBBCKeys(str) {
    return stringToKeys(str, bbcKeyForCharacter, BBC.SHIFT, BBC.CAPSLOCK);
}

