/**
 * Other names a `KEY.` parameter may use for a host key: one that covers both sides of a pair,
 * or a second name for a key that is printed differently on different keyboards.
 */
const keyCodeAliases = {
    SHIFT: [keyCodes.SHIFT_LEFT, keyCodes.SHIFT_RIGHT],
    CTRL: [keyCodes.CTRL_LEFT, keyCodes.CTRL_RIGHT],
    ALT: [keyCodes.ALT_LEFT, keyCodes.ALT_RIGHT],
    HASH: [keyCodes.BACKSLASH],
    /* an Apple keyboard prints "clear" on the key a PC calls num lock */
    CLEAR: [keyCodes.NUMLOCK],
};

/**
 * The host keys a jsbeeb key name stands for, or an empty array if it names none.
 * @param {string} name a `keyCodes` name, or an alias covering more than one
 * @returns {string[]} `KeyboardEvent.code` names
 */
export function hostKeyCodes(name) {
    if (keyCodes[name]) return [keyCodes[name]];
    return keyCodeAliases[name] ?? [];
}

export function detectKeyboardLayout() {
    if (runningInNode) {
        return "UK";
    }
    if (localStorage.keyboardLayout) {
        return localStorage.keyboardLayout === "US" ? "US" : "UK";
    }
    if (navigator.language) {
        if (navigator.language.toLowerCase() === "en-gb") return "UK";
        if (navigator.language.toLowerCase() === "en-us") return "US";
    }
    return "UK"; // Default guess of UK
}

/**
 * Whether a `KEY.` parameter has claimed this host key. Those name a key by where it is, so they
 * win over the character it prints in the layout that goes by character.
 * @param {string} code a `KeyboardEvent.code` name
 */
export function isUserRemapped(code) {
    return userKeymap.some((mapping) => hostKeyCodes(mapping.native).includes(code));
}

const Letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/**
 * What both machines' key maps are built with, the letters already bound. `finish()` applies the `KEY.` URL
 * parameters last, so they win, without consuming them: a map is rebuilt on layout and model changes, and the user's
 * mapping has to survive that.
 * @param {Object<string, number[]>} machineKeys the machine's keys by name, BBC or ATOM
 */
export function keyMapBuilder(machineKeys) {
    const keys = [];
    keys[true] = {};
    keys[false] = {};

    function bind(code, colRow, shiftDown) {
        if (keys[shiftDown][code] && keys[shiftDown][code] !== colRow) {
            console.log(
                "Warning: duplicate binding for key",
                (shiftDown ? "<SHIFT>" : "") + code,
                colRow,
                keys[shiftDown][code],
            );
        }
        keys[shiftDown][code] = colRow;
    }

    function map(code, colRow, shiftDown) {
        if (!code || !colRow) console.log("error binding key", code, colRow);
        if (shiftDown === undefined) {
            bind(code, colRow, true);
            bind(code, colRow, false);
        } else {
            bind(code, colRow, shiftDown);
        }
    }

    function finish() {
        for (const mapping of userKeymap) {
            for (const code of hostKeyCodes(mapping.native)) {
                keys[true][code] = machineKeys[mapping.key];
                keys[false][code] = machineKeys[mapping.key];
            }
        }
        return keys;
    }

    for (const letter of Letters) map(keyCodes[letter], machineKeys[letter]);
    return { map, finish };
}

export function getKeyMap(keyLayout) {
    const isUKlayout = detectKeyboardLayout() === "UK";
    const { map, finish } = keyMapBuilder(BBC);

    map(keyCodes.F10, BBC.F0); // F0 (mapped to F10)
    map(keyCodes.F1, BBC.F1);
    map(keyCodes.F2, BBC.F2);
    map(keyCodes.F3, BBC.F3);
    map(keyCodes.F4, BBC.F4);
    map(keyCodes.F5, BBC.F5);
    map(keyCodes.F6, BBC.F6);
    map(keyCodes.F7, BBC.F7);
    map(keyCodes.F8, BBC.F8);
    map(keyCodes.F9, BBC.F9);

    // these keys are in the same place on PC and BBC keyboards
    // including shifted characters
    // so can be the same for "natural" and "gaming"
    map(keyCodes.COMMA, BBC.COMMA);
    map(keyCodes.PERIOD, BBC.PERIOD);
    map(keyCodes.SLASH, BBC.SLASH);
    map(keyCodes.SPACE, BBC.SPACE);
    map(keyCodes.TAB, BBC.TAB);
    map(keyCodes.ENTER, BBC.RETURN);

    // see later map(keyCodes.SHIFT_LEFT, BBC.SHIFT_LEFT);
    map(keyCodes.SHIFT_RIGHT, BBC.SHIFT);

    // other keys to map to these in "game" layout too
    map(keyCodes.LEFT, BBC.LEFT);
    map(keyCodes.UP, BBC.UP);
    map(keyCodes.RIGHT, BBC.RIGHT);
    map(keyCodes.DOWN, BBC.DOWN);

    if (keyLayout === "natural") {
        // Keyed by the character the host keyboard produces, not by where a key sits, so the
        // host's own layout never has to be guessed: press whatever gives a `@` and the BBC
        // gets a `@`.
        const mapCharacter = characterBinder(map, bbcKeyForCharacter, ShiftMakesNoDifference);

        for (const char of PrintableCharacters) mapCharacter(char, char);

        // The BBC has no backtick, and a US or Dvorak keyboard cannot type a pound sign at all,
        // so the key that would print one gives the pound sign instead.
        mapCharacter(keyCodes.BACK_QUOTE, "\u00a3");

        // Keys that print nothing are still known by where they are.
        map(keyCodes.SHIFT_LEFT, BBC.SHIFT);
        map(keyCodes.END, BBC.COPY);
        map(keyCodes.HOME, BBC.SHIFTLOCK);
        map(keyCodes.F11, BBC.COPY);
        map(keyCodes.ESCAPE, BBC.ESCAPE);
        map(keyCodes.CTRL_LEFT, BBC.CTRL);
        map(keyCodes.CTRL_RIGHT, BBC.CTRL);
        map(keyCodes.CAPSLOCK, BBC.CAPSLOCK);
        map(keyCodes.DELETE, BBC.DELETE);
        map(keyCodes.BACKSPACE, BBC.DELETE);
    } else if (keyLayout === "gaming") {
        // gaming keyboard

        // 1st row
        map(keyCodes.ESCAPE, BBC.F0);

        // 2nd row
        map(keyCodes.BACK_QUOTE, BBC.ESCAPE);
        map(keyCodes.K1, BBC.K1);
        map(keyCodes.K2, BBC.K2);
        map(keyCodes.K3, BBC.K3);
        map(keyCodes.K4, BBC.K4);
        map(keyCodes.K5, BBC.K5);
        map(keyCodes.K6, BBC.K6);
        map(keyCodes.K7, BBC.K7);
        map(keyCodes.K8, BBC.K8);
        map(keyCodes.K9, BBC.K9);
        map(keyCodes.K0, BBC.K0);
        map(keyCodes.MINUS, BBC.MINUS);
        map(keyCodes.EQUALS, BBC.HAT_TILDE);
        map(keyCodes.BACKSPACE, BBC.PIPE_BACKSLASH);
        map(keyCodes.INSERT, BBC.LEFT);
        map(keyCodes.HOME, BBC.RIGHT);

        // 3rd row
        map(keyCodes.LEFT_SQUARE_BRACKET, BBC.AT);
        map(keyCodes.RIGHT_SQUARE_BRACKET, BBC.LEFT_SQUARE_BRACKET);
        // no key for BBC.UNDERSCORE_POUND in UK
        // see 4th row for US mapping keyCodes.BACKSLASH
        map(keyCodes.DELETE, BBC.UP);
        map(keyCodes.END, BBC.DOWN);

        // 4th row
        // no key for BBC.CAPSLOCK (mapped to CTRL_LEFT below)
        map(keyCodes.CAPSLOCK, BBC.CTRL);
        map(keyCodes.SEMICOLON, BBC.SEMICOLON_PLUS);
        map(keyCodes.APOSTROPHE, BBC.COLON_STAR);
        // UK prints `#~` on this key, a US board `\|`.
        map(keyCodes.BACKSLASH, isUKlayout ? BBC.RIGHT_SQUARE_BRACKET : BBC.UNDERSCORE_POUND);

        // Only a 102-key board has a key here, so only there can the left shift be spared.
        map(keyCodes.SHIFT_LEFT, isUKlayout ? BBC.SHIFTLOCK : BBC.SHIFT);
        map(keyCodes.INTL_BACKSLASH, BBC.SHIFT);

        // 5th row

        // for Zalaga
        map(keyCodes.CTRL_LEFT, BBC.CAPSLOCK);
        map(keyCodes.ALT_LEFT, BBC.CTRL);

        // should be 4th row, not enough keys
        map(keyCodes.MENU, BBC.DELETE);
        map(keyCodes.CTRL_RIGHT, BBC.COPY);

        // not in correct location
        map(keyCodes.ALT_RIGHT, BBC.SHIFTLOCK);
    } else {
        // Physical, and default
        map(keyCodes.K1, BBC.K1);
        map(keyCodes.K2, BBC.K2);
        map(keyCodes.K3, BBC.K3);
        map(keyCodes.K4, BBC.K4);
        map(keyCodes.K5, BBC.K5);
        map(keyCodes.K6, BBC.K6);
        map(keyCodes.K7, BBC.K7);
        map(keyCodes.K8, BBC.K8);
        map(keyCodes.K9, BBC.K9);
        map(keyCodes.K0, BBC.K0);
        map(keyCodes.SHIFT_LEFT, BBC.SHIFT);
        map(keyCodes.EQUALS, BBC.HAT_TILDE); // ^~ on +/=
        map(keyCodes.SEMICOLON, BBC.SEMICOLON_PLUS); // ';' / '+'
        map(keyCodes.MINUS, BBC.MINUS); // '-' / '=' mapped to underscore
        map(keyCodes.LEFT_SQUARE_BRACKET, BBC.LEFT_SQUARE_BRACKET); // maps to [{
        map(keyCodes.RIGHT_SQUARE_BRACKET, BBC.RIGHT_SQUARE_BRACKET); // maps to ]}
        map(keyCodes.COMMA, BBC.COMMA); // ',' / '<'
        map(keyCodes.PERIOD, BBC.PERIOD); // '.' / '>'
        map(keyCodes.SLASH, BBC.SLASH); // '/' / '?'
        map(keyCodes.TAB, BBC.TAB); // tab
        map(keyCodes.ENTER, BBC.RETURN); // return
        map(keyCodes.DELETE, BBC.DELETE); // delete
        map(keyCodes.BACKSPACE, BBC.DELETE); // delete
        map(keyCodes.END, BBC.COPY); // copy key is end
        map(keyCodes.HOME, BBC.SHIFTLOCK);
        map(keyCodes.F11, BBC.COPY); // copy key is end for Apple
        map(keyCodes.ESCAPE, BBC.ESCAPE); // escape
        map(keyCodes.CTRL_LEFT, BBC.CTRL);
        map(keyCodes.CTRL_RIGHT, BBC.CTRL);
        map(keyCodes.CAPSLOCK, BBC.CAPSLOCK); // caps (on Rich's/Mike's computer)
        map(keyCodes.LEFT, BBC.LEFT); // arrow left
        map(keyCodes.UP, BBC.UP); // arrow up
        map(keyCodes.RIGHT, BBC.RIGHT); // arrow right
        map(keyCodes.DOWN, BBC.DOWN); // arrow down
        map(keyCodes.APOSTROPHE, BBC.COLON_STAR);

        // None of this last group in great locations.
        // But better to have them mapped at least somewhere.
        map(keyCodes.BACK_QUOTE, BBC.AT);
        map(keyCodes.BACKSLASH, BBC.PIPE_BACKSLASH);
        map(keyCodes.INTL_BACKSLASH, BBC.PIPE_BACKSLASH);
        map(keyCodes.PAGEUP, BBC.UNDERSCORE_POUND);
    }

    // Master
    map(keyCodes.NUMPAD0, BBC.NUMPAD0);
    map(keyCodes.NUMPAD1, BBC.NUMPAD1);
    map(keyCodes.NUMPAD2, BBC.NUMPAD2);
    map(keyCodes.NUMPAD3, BBC.NUMPAD3);
    map(keyCodes.NUMPAD4, BBC.NUMPAD4);
    map(keyCodes.NUMPAD5, BBC.NUMPAD5);
    map(keyCodes.NUMPAD6, BBC.NUMPAD6);
    map(keyCodes.NUMPAD7, BBC.NUMPAD7);
    map(keyCodes.NUMPAD8, BBC.NUMPAD8);
    map(keyCodes.NUMPAD9, BBC.NUMPAD9);
    map(keyCodes.NUMPAD_DECIMAL_POINT, BBC.NUMPAD_DECIMAL_POINT);

    // "natural" mapping
    map(keyCodes.NUMPADPLUS, BBC.NUMPADPLUS);
    map(keyCodes.NUMPADMINUS, BBC.NUMPADMINUS);
    map(keyCodes.NUMPADSLASH, BBC.NUMPADSLASH);
    map(keyCodes.NUMPADASTERISK, BBC.NUMPADASTERISK);
    //map(???, BBC.NUMPADCOMMA);
    //map(???, BBC.NUMPADHASH);
    map(keyCodes.NUMPADENTER, BBC.NUMPADENTER);

    // TODO(#748) "game" mapping
    // eg Master Dunjunz needs # Del 3 , * Enter
    // https://web.archive.org/web/20080305042238/http://bbc.nvg.org/doc/games/Dunjunz-docs.txt

    return finish();
}

/**
 * Who holds SHIFT on a key matrix driven by mappings from a key map. A mapping of
 * `[col, row, shiftOverride]` forces SHIFT to its override while that key is down; otherwise
 * SHIFT follows the mapped shift key. Keys set on the matrix directly bypass it, and a SHIFT
 * set that way survives plain mapped keys but not the shift key or a forcing key. Two mappings
 * can share a matrix key (the Atom's arrows share its cursor keys), so a key stays down while
 * any mapping holds it, and the latest forcing mapping still held decides SHIFT.
 */
export class ShiftOverride {
    constructor([shiftCol, shiftRow]) {
        this.shiftCol = shiftCol;
        this.shiftRow = shiftRow;
        this.held = new Map();
        this.clear();
    }

    clear() {
        this.physicalShiftDown = false;
        this.forcedShift = null;
        this.held.clear();
    }

    setMapped(keys, mapping, val) {
        const [col, row, shiftOverride] = mapping;
        const id = ShiftOverride.#heldId(mapping);
        this.held.delete(id);
        if (val) this.held.set(id, mapping);
        const held = [...this.held.values()];
        keys[col][row] = val || held.some(([c, r]) => c === col && r === row) ? 1 : 0;
        const isShiftKey = shiftOverride === undefined && col === this.shiftCol && row === this.shiftRow;
        if (isShiftKey) this.physicalShiftDown = !!val;
        if (shiftOverride !== undefined) {
            this.forcedShift = held.findLast(([, , override]) => override !== undefined)?.[2] ?? null;
        }
        if (isShiftKey || shiftOverride !== undefined || this.forcedShift !== null) {
            keys[this.shiftCol][this.shiftRow] = (this.forcedShift ?? this.physicalShiftDown) ? 1 : 0;
        }
    }

    // Part of keyboardState(), which shared-session peers on different deploys of one
    // package version exchange.
    state() {
        return {
            physicalShiftDown: this.physicalShiftDown,
            shiftOverrideActive: this.forcedShift !== null,
            shiftOverrideDesiredShift: !!this.forcedShift,
            heldMappings: [...this.held.values()].map((mapping) => [...mapping]),
        };
    }

    restore({ physicalShiftDown, shiftOverrideActive, shiftOverrideDesiredShift, heldMappings }) {
        this.physicalShiftDown = physicalShiftDown;
        this.forcedShift = shiftOverrideActive ? shiftOverrideDesiredShift : null;
        this.held.clear();
        for (const mapping of heldMappings ?? []) this.held.set(ShiftOverride.#heldId(mapping), mapping);
    }

    // By value, since a shared session's peers hand mappings over as copies.
    static #heldId([col, row, shiftOverride]) {
        return `${col},${row},${shiftOverride}`;
    }
}

export const KeyMatrixSize = 16;
const KeyMatrixRows = 8;

/**
 * The keyboard half of the BBC's system VIA and the Atom's PPIA: a key matrix that host keys are mapped onto. The
 * owner calls `_initKeyMatrix` from its constructor, provides `keycodeToRowCol` (a key map) and `updateKeys()`, and
 * sees every change through `_keysChanged()`.
 * @template {new (...args: any[]) => object} TBase
 * @param {TBase} Base
 */
export const WithKeyMatrix = (Base) =>
    class extends Base {
        /**
         * @param {number[]} shiftKey where SHIFT is on the matrix
         * @param {number} columns how many of the matrix's columns hold keys
         */
        _initKeyMatrix(shiftKey, columns) {
            this.keys = Array.from({ length: KeyMatrixSize }, () => new Uint8Array(KeyMatrixSize));
            this.keyColumns = columns;
            this.shift = new ShiftOverride(shiftKey);
            this.keyboardEnabled = true;
            /** @type {import("./replay.js").InputLog | null} */
            this.inputLog = null;
        }

        /**
         * The keys held down, which snapshots leave out so that a rewind or a loaded state
         * keeps the keys the person is actually holding.
         */
        keyboardState() {
            return {
                keys: this.keys.map((column) => Array.from(column)),
                ...this.shift.state(),
            };
        }

        restoreKeyboard(state) {
            state.keys.forEach((column, col) => this.keys[col].set(column));
            this.shift.restore(state);
            this.updateKeys();
        }

        clearKeys() {
            for (const column of this.keys) column.fill(0);
            this.shift.clear();
            this._keysChanged();
        }

        disableKeyboard() {
            this.keyboardEnabled = false;
            this.clearKeys();
        }

        enableKeyboard() {
            this.keyboardEnabled = true;
            this.clearKeys();
        }

        set(key, val, shiftDown) {
            const mapping = this.keyMapping(key, shiftDown);
            if (mapping) this.setMapped(mapping, val);
        }

        /**
         * Where a key code lands on the key matrix under the current layout, as `[col, row, shiftOverride?]`, or
         * undefined.
         */
        keyMapping(key, shiftDown) {
            return this.keycodeToRowCol[!!shiftDown][key];
        }

        setMapped(mapping, val) {
            if (!this.keyboardEnabled) return;
            this.shift.setMapped(this.keys, mapping, val);
            this._keysChanged();
        }

        keyDown(key, shiftDown) {
            this.set(key, 1, shiftDown);
        }

        /** Releases the key under both the shifted and unshifted maps, whichever pressed it. */
        keyUp(key) {
            this.set(key, 0, true);
            this.set(key, 0, false);
        }

        keyDownRaw([col, row]) {
            this.keys[col][row] = 1;
            this._keysChanged();
        }

        keyUpRaw([col, row]) {
            this.keys[col][row] = 0;
            this._keysChanged();
        }

        keyToggleRaw([col, row]) {
            this.keys[col][row] = 1 - this.keys[col][row];
            this._keysChanged();
        }

        _keysChanged() {
            this.updateKeys();
            this.inputLog?.record({ kind: "keyboard", state: this.keyboardState() });
        }

        hasAnyKeyDown() {
            return this.keys
                .slice(0, this.keyColumns)
                .some((column) => column.subarray(0, KeyMatrixRows).some(Boolean));
        }
    };
