const PrevInstructionWindow = 64;
const PcInRunScore = 10;
const CommonInstructions =
    /^(?:RTS|B(?:CC|CS|EQ|NE|MI|PL|VC|VS|RA|IT)|JMP|JSR|LD[AXY]|ST[AXY]|TA[XY]|T[XY]A|ADC|SBC|CLC|SEC|CMP|EOR|ORA|AND|INC|DEC)\b/;
const UncommonInstructions = /,\s*([XY]|X\))$/;
const ModesWithoutMemoryOperand = new Set(["implied", "A", "imm"]);

function instructionLength(mode) {
    if (mode === "implied" || mode === "A") return 1;
    return mode.includes("abs") || mode === "zp,branch" ? 3 : 2;
}

const ProbePc = 0x2000;
// Whether an instruction settles can hang on the values it meets (TSB settles at once if A shares a bit with memory),
// so it runs from two states unlike in every register and flag, the second's memory sharing no bit with its A.
const ProbeStates = [
    { a: 0x5a, x: 0x3c, y: 0xc3, s: 0xe0, flags: 0x00, fill: (address) => (address * 7 + 0x35) & 0xff },
    { a: 0xa5, x: 0xc3, y: 0x3c, s: 0x1f, flags: 0xff, fill: (address) => (address * 13 + 0x9a) & 0x5a },
];

/**
 * Runs `instruction` once from `state` on a stand-in for `cpu`, whose own methods (adc, push, brk...) then work on
 * the stand-in's registers, flags and memory; returns the state it leaves.
 */
function runOnStandIn(cpu, instruction, { a, x, y, s, flags, fill, memory }) {
    const p = Object.create(Object.getPrototypeOf(cpu.p));
    p.setFromByte(flags);
    const written = new Map(memory);
    const readmem = (address) => written.get(address & 0xffff) ?? fill(address & 0xffff);
    const writemem = (address, value) => written.set(address & 0xffff, value & 0xff);
    const noop = () => {};
    const standIn = Object.assign(Object.create(cpu), { a, x, y, s, p, pc: ProbePc, readmem, writemem });
    Object.assign(standIn, { readmemZpStack: readmem, writememZpStack: writemem });
    Object.assign(standIn, { polltime: noop, polltimeAddr: noop, checkInt: noop, branch: noop });
    instruction(standIn);
    return { a: standIn.a, x: standIn.x, y: standIn.y, s: standIn.s, flags: p.asByte(), fill, memory: written };
}

function measureIdempotence(cpu, instruction) {
    return ProbeStates.every((state) => {
        const once = runOnStandIn(cpu, instruction, state);
        const twice = runOnStandIn(cpu, instruction, once);
        const sameMemory = [...twice.memory].every(
            ([address, value]) => (once.memory.get(address) ?? once.fill(address)) === value,
        );
        return sameMemory && ["a", "x", "y", "s", "flags"].every((name) => once[name] === twice[name]);
    });
}

const UnknownOpcode = { mnemonic: "???", mode: "implied", length: 1, accesses: [], flow: "next" };

/**
 * @typedef {"next" | "branch" | "jump" | "call" | "return" | "interrupt"} Flow
 * @typedef {object} OpcodeDescription
 * @property {string} mnemonic
 * @property {string} mode the addressing mode, as the opcode tables spell it, or "implied"
 * @property {number} length in bytes, with its operand
 * @property {("read" | "write")[]} accesses what it does to the memory its operand addresses
 * @property {Flow} flow
 */

/** @returns {OpcodeDescription[]} by opcode, from what the emulation itself does with each */
function describeOpcodes(opcodes) {
    const descriptions = [];
    for (const [opcode, text] of Object.entries(opcodes)) {
        const [mnemonic, mode = "implied"] = text.split(" ");
        const { read, write, flow } = getOp(mnemonic, mode === "implied" ? undefined : mode);
        const memory = !ModesWithoutMemoryOperand.has(mode);
        descriptions[Number(opcode)] = {
            mnemonic,
            mode,
            length: instructionLength(mode),
            accesses: [...(memory && read ? ["read"] : []), ...(memory && write ? ["write"] : [])],
            flow: flow ?? (mode.endsWith("branch") ? "branch" : "next"),
        };
    }
    return descriptions;
}

class Disassemble6502 {
    constructor(cpu, opcodes, undocumented, compile) {
        this.cpu = cpu;
        this.opcodes = opcodes;
        this.undocumented = undocumented;
        this.descriptions = describeOpcodes(opcodes);
        this.compile = compile;
        this.idempotence = [];
    }

    /**
     * Whether running the opcode's emulation again at once, with memory as it left it, changes nothing more in the
     * registers, flags or memory; measured by running it, on first asking.
     */
    isIdempotent(opcode) {
        if (!(opcode in this.opcodes)) return false;
        this.idempotence[opcode] ??= measureIdempotence(this.cpu, this.compile(this.opcodes[opcode]));
        return this.idempotence[opcode];
    }

    /** @returns {OpcodeDescription} */
    describeOpcode(opcode) {
        return this.descriptions[opcode] ?? UnknownOpcode;
    }

    /**
     * The instruction at `addr`: its opcode's description, the address after it (not wrapped past $ffff), the
     * memory its direct-mode operand addresses, and where it may go when the code alone says.
     * @returns {OpcodeDescription & {next: number, address?: number, target?: number}}
     */
    instructionAt(addr) {
        const peek = (offset) => this.cpu.peekmem(addr + offset);
        const description = this.describeOpcode(peek(0));
        const { mode, length, flow } = description;
        const instruction = { ...description, next: addr + length };
        if (mode === "zp" || mode === "zp,branch") instruction.address = peek(1);
        if (mode === "abs") instruction[flow === "next" ? "address" : "target"] = peek(1) | (peek(2) << 8);
        if (flow === "branch") instruction.target = (instruction.next + signExtend(peek(length - 1))) & 0xffff;
        return instruction;
    }

    /** The same disassembler reading memory with `peek` instead of the CPU's peekmem. */
    reading(peek) {
        return new Disassemble6502({ peekmem: peek }, this.opcodes, this.undocumented);
    }

    isDocumented(addr) {
        return this.isDocumentedOpcode(this.cpu.peekmem(addr));
    }

    isDocumentedOpcode(op) {
        return op in this.opcodes && !this.undocumented.has(op);
    }

    disassemble(addr, plain) {
        const ref = (kind, addr, hex) =>
            plain ? `$${hex(addr)}` : `<span class="${kind}" data-ref="${addr}">$${hex(addr)}</span>`;
        const formatAddr = (addr) => ref("instr_mem_ref", addr, hexword);
        const formatZpAddr = (addr) => ref("instr_mem_ref", addr, hexbyte);
        const formatJumpAddr = (addr) => ref("instr_instr_ref", addr, hexword);
        const { mnemonic, mode, flow, next, address, target } = this.instructionAt(addr);
        const name = (this.undocumented.has(this.cpu.peekmem(addr)) ? "*" : "") + mnemonic;
        if (mode === "implied") return [name, next];
        let param = mode;
        let suffix = "";
        let suffix2 = "";
        const index = param.match(/(.*),([xy])$/);
        if (index) {
            param = index[1];
            suffix = `,${index[2].toUpperCase()}`;
            suffix2 = ` + ${index[2].toUpperCase()}`;
        }
        switch (param) {
            case "imm":
                return [`${name} #$${hexbyte(this.cpu.peekmem(addr + 1))}${suffix}`, next];
            case "abs": {
                const destAddr = this.cpu.peekmem(addr + 1) | (this.cpu.peekmem(addr + 2) << 8);
                const formatter = flow === "next" ? formatAddr : formatJumpAddr;
                return [`${name} ${formatter(destAddr)}${suffix}`, next];
            }
            case "branch":
                return [`${name} ${formatJumpAddr(target)}${suffix}`, next];
            case "zp":
                return [`${name} ${formatZpAddr(this.cpu.peekmem(addr + 1))}${suffix}`, next];
            case "zp,branch":
                return [`${name} ${formatZpAddr(address)}, ${formatJumpAddr(target)}`, next];
            case "(,x)":
                return [`${name} (${formatZpAddr(this.cpu.peekmem(addr + 1))}, X)${suffix}`, next];
            case "()": {
                const zp = this.cpu.peekmem(addr + 1);
                const destAddr = this.cpu.peekmem(zp) | (this.cpu.peekmem(zp + 1) << 8);
                return [`${name} (${formatZpAddr(zp)})${suffix} ; $${hexword(destAddr)}${suffix2}`, next];
            }
            case "(abs)": {
                const destAddr = this.cpu.peekmem(addr + 1) | (this.cpu.peekmem(addr + 2) << 8);
                const indDest = this.cpu.peekmem(destAddr) | (this.cpu.peekmem(destAddr + 1) << 8);
                return [`${name} (${formatJumpAddr(destAddr)})${suffix} ; $${hexword(indDest)}${suffix2}`, next];
            }
            case "(abs,x)": {
                const destAddr = this.cpu.peekmem(addr + 1) | (this.cpu.peekmem(addr + 2) << 8);
                return [`${name} (${formatJumpAddr(destAddr)},X)${suffix}`, next];
            }
        }
        return [`${name} ${mode}`, next];
    }

    nextInstruction(address) {
        return this.instructionAt(address).next & 0xffff;
    }

    /**
     * Guesses the address of the instruction before the given one by scoring
     * each run of instructions in the preceding window that lands exactly on
     * it: a point per "common" instruction (loads, stores, branches, compares,
     * arithmetic and carry-set/clear that avoid unusual indexing modes) and a
     * large boost for a run that passes through pc. Runs through undocumented
     * opcodes are discarded. The highest-scoring run's last instruction wins;
     * any run beats none, since a wrong parse resynchronises within a few
     * instructions and so nearly always shares the true stream's last one.
     * Good test cases:
     *   Repton 2 @ 2cbb
     *   MOS @ cfc8, and the unrolled STA abs,X screen clear @ cc63
     * also, just starting from the back of ROM and going up...
     */
    prevInstruction(address, pc) {
        address &= 0xffff;
        const windowStart = Math.max(address - PrevInstructionWindow, 0);
        // A run's score is its first instruction's plus that of the run from where that instruction ends.
        const runs = new Array(address - windowStart);
        for (let addr = address - 1; addr >= windowStart; addr--) {
            if (!this.isDocumented(addr)) continue;
            const [text, next] = this.disassemble(addr);
            const isCommon = CommonInstructions.test(text) && !UncommonInstructions.test(text);
            const score = (addr === pc ? PcInRunScore : 0) + (isCommon ? 1 : 0);
            if (next === address) {
                runs[addr - windowStart] = { score, last: addr };
            } else if (next < address) {
                const rest = runs[next - windowStart];
                if (rest) runs[addr - windowStart] = { score: score + rest.score, last: rest.last };
            }
        }
        let best = null;
        for (const run of runs) {
            if (run && (!best || run.score > best.score)) best = run;
        }
        return best ? best.last : (address - 1) & 0xffff;
    }
}

function nmosIndexedStoreRead(ig, op) {
    // Pure stores still exhibit a read at the non-carried address.
    ig.readOp("addrNonCarry");
    // with this quirk on undocumented instructions, a page crossing writes to 00XX
    if (op.zpQuirk) ig.append("if (addrWithCarry !== addrNonCarry) addrWithCarry &= 0xff;");
}

function makeCpuFunctions(cpu, cpuType, opcodes, undocumented, is65c12, cycleAccurate) {
    function getInstruction(opcodeString, needsReg) {
        const split = opcodeString.split(" ");
        const opcode = split[0];
        const arg = split[1];
        const op = getOp(opcode, arg);
        if (!op) return null;

        let ig = new InstructionGen(is65c12, cycleAccurate);
        if (needsReg) ig.append("let REG = 0|0;");

        switch (arg) {
            case undefined:
                // Many of these ops need a little special casing.
                if (op.read || op.write) throw new Error(`Unsupported ${opcodeString}`);
                ig.append(op.preop);
                ig.tick(Math.max(2, 1 + (op.extra || 0)));
                ig.append(op.op);
                return ig.render();

            case "branch":
                return [op.op]; // special cased here, would be nice to pull out of cpu

            case "zp,branch":
                ig.tick(2);
                ig.append("const addr = cpu.getb() | 0;");
                ig.zpOperandOp(op, "addr");
                return ig.render();

            case "zp":
            case "zp,x":
            case "zp,y":
                if (arg === "zp") {
                    ig.tick(2);
                    ig.append("const addr = cpu.getb() | 0;");
                } else {
                    ig.tick(3);
                    ig.append(`const addr = (cpu.getb() + cpu.${arg[3]}) & 0xff;`);
                }
                ig.zpOperandOp(op, "addr");
                return ig.render();

            case "abs":
                ig.tick(3 + (op.extra || 0));
                ig.append("const addr = cpu.getw() | 0;");
                ig.operandOp(op, "addr");
                return ig.render();

            case "abs,x":
            case "abs,y":
                ig.append("const addr = cpu.getw() | 0;");
                ig.append(`let addrWithCarry = (addr + cpu.${arg[4]}) & 0xffff;`);
                ig.append("const addrNonCarry = (addr & 0xff00) | (addrWithCarry & 0xff);");
                ig.tick(3);
                ig = ig.split("addrWithCarry !== addrNonCarry");
                if (op.read && !op.write) {
                    if (is65c12) {
                        // the 65c12 reads the instruction byte again while it's carrying.
                        ig.ifTrue.tick(1);
                    } else {
                        // the 6502 reads the uncarried address
                        ig.ifTrue.readOp("addrNonCarry");
                    }
                    ig.readOp("addrWithCarry", "REG");
                } else if (op.read) {
                    if (is65c12) {
                        // RMWs on 65c12 burn a cycle reading the instruction byte again while carrying.
                        ig.ifTrue.tick(1);
                        // For anything but rotates, there's a bug: during carrying the CPU reads again.
                        // beebjit reads the carried address, but I can't see how that could be the case,
                        // so I read the non-carry here.
                        if (!op.rotate) ig.ifFalse.readOp("addrNonCarry", "REG");
                        ig.readOp("addrWithCarry", "REG");
                        // 65c12 does "two reads and one write" for RMW (not the 6502's
                        // "one read and two writes"). The spurious cycle is a read.
                        ig.readOp("addrWithCarry", "", true);
                    } else {
                        // For RMW we always have a spurious read and then a spurious read or write
                        ig.readOp("addrNonCarry");
                        ig.readOp("addrWithCarry", "REG");
                        ig.spuriousOp("addrWithCarry", "REG");
                    }
                } else if (op.write) {
                    if (is65c12) {
                        // Discovered on Stardot: https://stardot.org.uk/forums/viewtopic.php?f=55&t=25298&sid=86e65177447d407aa6510f1f98efca87&start=30
                        // With page crossing, the CPU re-reads the third byte of the instruction.
                        ig.ifTrue.tick(1);
                        // Without page crossing, the CPU still has the bug of reading the non-carried address(!)
                        ig.ifFalse.readOp("addrNonCarry");
                    } else {
                        nmosIndexedStoreRead(ig, op);
                    }
                }
                ig.append(op.op);
                if (op.write) ig.writeOp("addrWithCarry", "REG");
                return ig.render();

            case "imm":
                if (op.write) {
                    throw new Error("This isn't possible");
                }
                ig.tick(2);
                ig.append("REG = cpu.getb() | 0;");
                ig.append(op.op);
                return ig.render();

            case "A":
                ig.tick(2);
                ig.append("REG = cpu.a;");
                ig.append(op.op);
                ig.append("cpu.a = REG;");
                return ig.render();

            case "(,x)":
                ig.tick(3); // two, plus one for the seemingly spurious extra read of zp
                ig.append("const zpAddr = (cpu.getb() + cpu.x) & 0xff;");
                ig.pointerOp("zpReadOp", "zpAddr", "(zpAddr + 1) & 0xff");
                ig.operandOp(op, "addr");
                return ig.render();

            case "(),y":
                ig.tick(2);
                ig.append("const zpAddr = cpu.getb() | 0;");
                ig.pointerOp("zpReadOp", "zpAddr", "(zpAddr + 1) & 0xff");
                ig.append("let addrWithCarry = (addr + cpu.y) & 0xffff;");
                ig.append("const addrNonCarry = (addr & 0xff00) | (addrWithCarry & 0xff);");
                if (op.read && !op.write) {
                    // For non-RMW, we only pay the cost of the spurious read if the address carried on 6502
                    ig = ig.split("addrWithCarry !== addrNonCarry");
                    if (!is65c12) {
                        ig.ifTrue.readOp("addrNonCarry");
                    } else {
                        ig.ifTrue.tick(1);
                    }
                    ig.readOp("addrWithCarry", "REG");
                } else if (op.read) {
                    // For RMW we always have a spurious read and then a spurious read or write
                    ig.readOp("addrNonCarry");
                    ig.readOp("addrWithCarry", "REG");
                    ig.spuriousOp("addrWithCarry", "REG");
                } else if (op.write) {
                    if (is65c12) {
                        // On the 65c12, the dead cycle reads the Previous Bus Address (PBA)
                        // rather than the partially-formed or target address. Since PBA is
                        // always a zero-page or instruction-fetch address (2MHz), it never
                        // triggers 1MHz bus stretching. We model this as tick(1).
                        ig.tick(1);
                    } else {
                        nmosIndexedStoreRead(ig, op);
                    }
                }
                ig.append(op.op);
                if (op.write) ig.writeOp("addrWithCarry", "REG");
                return ig.render();

            case "(abs)":
                ig.tick(is65c12 ? 4 : 3);
                ig.append("const absAddr = cpu.getw() | 0;");
                if (is65c12) {
                    ig.append("const nextAddr = (absAddr + 1) & 0xffff;");
                } else {
                    ig.append("const nextAddr = ((absAddr + 1) & 0xff) | (absAddr & 0xff00);");
                }
                ig.pointerOp("readOp", "absAddr", "nextAddr");
                ig.append(op.op);
                return ig.render();

            case "(abs,x)":
                ig.tick(4);
                ig.append("const absAddr = (cpu.getw() + cpu.x) | 0;");
                ig.pointerOp("readOp", "absAddr", "(absAddr + 1) & 0xffff");
                ig.append(op.op);
                return ig.render();

            case "()":
                // Timing here is guessed at, but appears to be correct.
                ig.tick(2);
                ig.append("const zpAddr = cpu.getb() | 0;");
                ig.pointerOp("zpReadOp", "zpAddr", "(zpAddr + 1) & 0xff");
                if (op.read) ig.readOp("addr", "REG");
                ig.append(op.op);
                if (op.write) ig.writeOp("addr", "REG");
                return ig.render();

            default:
                throw new Error(`Unknown arg type ${arg}`);
        }
    }

    function getIndentedSource(indent, opcodeNum, needsReg) {
        const opcode = opcodes[opcodeNum];
        return (
            indent +
            [
                '"use strict";',
                `// ${hexbyte(opcodeNum)} - ${opcode}
`,
            ].concat(
                opcode ? getInstruction(opcode, !!needsReg) : [`this.invalidOpcode(cpu, 0x${hexbyte(opcodeNum)});`],
            ).join(`
${indent}`)
        );
    }

    // Empty to hold prototypical stuff.
    function Runner() {}

    function opcodeFunctionName(opcodeNum) {
        const opcode = opcodes[opcodeNum];
        const instrName = opcode
            ? opcode
                  .replace("()", "ind")
                  .replace("(,x)", "ind_x")
                  .replace("(abs)", "ind_abs")
                  .replace(/[^A-Za-z0-9]/g, "_")
                  .toLowerCase()
            : "undef";
        return `exec_${hexbyte(opcodeNum)}_${instrName}`;
    }

    function generate6502JumpTable() {
        const funcs = [];
        for (let opcodeNum = 0; opcodeNum < 256; ++opcodeNum) {
            const name = opcodeFunctionName(opcodeNum);
            const source = getIndentedSource("  ", opcodeNum, true);
            // Only a declared name reaches every profiler (Firefox's ignores the sourceURL), and assigning `name`
            // afterwards puts the function in dictionary mode, which slows the dispatch's `.call`.
            funcs[opcodeNum] = new Function(
                `return function ${name}(cpu) {\n${source}\n};\n//# sourceURL=${cpuType}/${name}.js`,
            )();
        }
        return function exec(opcode) {
            return funcs[opcode].call(this, this.cpu);
        };
    }

    function invalidOpcode(cpu, opcode) {
        if (is65c12) {
            // All undefined opcodes are NOPs on 65c12 (of varying lengths)
            // http://6502.org/tutorials/65c02opcodes.html has a list.
            // The default case is to treat them as one-cycle NOPs. Anything more than this is picked up below.
            switch (opcode) {
                case 0x02:
                case 0x22:
                case 0x42:
                case 0x62:
                case 0x82:
                case 0xc2:
                case 0xe2:
                    // two bytes, two cycles
                    cpu.getb();
                    cpu.polltime(2);
                    break;

                case 0x44:
                    // two bytes, three cycles
                    cpu.getb();
                    cpu.polltime(3);
                    break;

                case 0x54:
                case 0xd4:
                case 0xf4:
                    // two bytes, four cycles
                    cpu.getb();
                    cpu.polltime(4);
                    break;

                case 0x5c:
                    // three bytes, eight cycles
                    cpu.getw();
                    cpu.polltime(8);
                    break;

                case 0xdc:
                case 0xfc:
                    // three bytes, four cycles (plus a memory access)
                    cpu.polltimeAddr(4, cpu.getw());
                    break;

                default:
                    // one byte one cycle
                    cpu.polltime(1);
                    break;
            }
            return;
        }
        // Anything else is a HLT. Just hang forever...
        cpu.pc--; // Account for the fact we've already incremented pc.
        cpu.polltime(1); // Take up some time though. Else we'll spin forever
    }

    Runner.prototype.invalidOpcode = invalidOpcode;
    Runner.prototype.cpu = cpu;
    // We used to use jump tables for Firefox, and binary search for everything else.
    // Chrome used to have a problem with 256 entries in a switch, but that seems to have been fixed.
    // We now use a jump table for everything.
    Runner.prototype.run = generate6502JumpTable();

    return {
        disassembler: new Disassemble6502(
            cpu,
            opcodes,
            undocumented,
            (text) => new Function("cpu", [getInstruction(text, true)].flat().join("\n")),
        ),
        runInstruction: new Runner(),
    };
}

export function Cpu6502(cpu, { cycleAccurate = true } = {}) {
    return makeCpuFunctions(cpu, "6502", opcodes6502, undocumented6502, false, cycleAccurate);
}

export function Cpu65c12(cpu, { cycleAccurate = true } = {}) {
    return makeCpuFunctions(cpu, "65c12", opcodes65c12, undocumented65c12, true, cycleAccurate);
}

export function Cpu65c02(cpu, { cycleAccurate = true } = {}) {
    return makeCpuFunctions(cpu, "65c02", opcodes65c02, undocumented65c02, true, cycleAccurate);
}
